import { requireAdminPage } from "@/lib/admin/page-auth";
import { listUsers } from "@/lib/admin/queries";
import { UsersTable } from "@/components/admin/users-table";
import { AdminNotice, CursorLink } from "@/components/admin/common";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
export default async function UsersPage({
  searchParams,
}: {
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  await requireAdminPage();
  const params = await searchParams;
  const filters = Object.fromEntries(
    Object.entries(params).filter(([, v]) => v !== ""),
  );
  let data;
  try {
    data = await listUsers(filters);
  } catch {
    return <AdminNotice />;
  }
  return (
    <>
      <h1 className="text-3xl font-semibold">Users</h1>
      <form className="flex flex-wrap items-end gap-4">
        <label>
          Search name or email
          <Input
            name="search"
            maxLength={160}
            defaultValue={
              typeof params.search === "string" ? params.search : ""
            }
          />
        </label>
        <label>
          Effective plan
          <select
            name="plan"
            defaultValue={(params.plan as string) ?? ""}
            className="block min-h-11 border bg-surface px-3"
          >
            <option value="">All plans</option>
            <option>FREE</option>
            <option>PAID</option>
          </select>
        </label>
        <label>
          Subscription
          <select
            name="status"
            defaultValue={(params.status as string) ?? ""}
            className="block min-h-11 border bg-surface px-3"
          >
            <option value="">All statuses</option>
            {[
              "NONE",
              "PENDING",
              "ACTIVE",
              "PAST_DUE",
              "ON_HOLD",
              "CANCELLED",
              "EXPIRED",
              "FAILED",
              "PAUSED",
            ].map((s) => (
              <option key={s}>{s}</option>
            ))}
          </select>
        </label>
        <label>
          Suspension
          <select
            name="suspended"
            defaultValue={(params.suspended as string) ?? ""}
            className="block min-h-11 border bg-surface px-3"
          >
            <option value="">All accounts</option>
            <option value="true">Suspended</option>
            <option value="false">Not suspended</option>
          </select>
        </label>
        <Button>Apply filters</Button>
      </form>
      <UsersTable users={data.users} />
      <CursorLink
        path="/admin/users"
        cursor={data.nextCursor}
        filters={filters as Record<string, string>}
      />
    </>
  );
}
